; Writes score, bombs, altitude, speed and fuel to the status rows. The speed is grey and SPEED blinks below the lift-off speed 100.
main_loop_draw_status
        jsr draw_score
        ldx #$3d                        ; Bombs: 2 digits at column $3d.
        lda bombs
        jsr print_number_2
        ldx #$07                        ; Altitude $40da: 2 digits at column 7.
        lda altitude
        jsr print_number_2
        ldx #$2f
        lda speed
        cmp #$64                        ; Lift-off speed is 100.
        bcs main_loop_speed_white
        lda frame_count
        and #$10
        bne main_loop_speed_dark
        ldy #$01
        jmp main_loop_speed_grey
main_loop_speed_dark
        ldy #$00
main_loop_speed_grey
        lda #$0c
        jmp main_loop_speed_colour
main_loop_speed_white
        ldy #$01
        lda #$01
main_loop_speed_colour
        sta $db70,x                     ; Colour of the speed digits at $db9f-$dba1.
        sta $db71,x
        sta $db72,x
        sty $db99                       ; Colour of the word SPEED at $db99-$db9d.
        sty $db9a
        sty $db9b
        sty $db9c
        sty $db9d
        lda speed
        jsr print_number_3
        ldx #$15                        ; Fuel $4061: 3 digits at column $15.
        lda fuel
        jsr print_number_3
        ldx #$03
; Shows the damage letters F B M G from the flags $40b9-$40bc at $0f8e, $0f90, $0f92, $0f94. They blink white and yellow.
main_loop_damage_loop
        txa
        asl
        tay
        lda damage_fuel,x
        bne main_loop_damage_letter
        lda #$20
        sta $0f8e,y
        jmp main_loop_damage_next
main_loop_damage_letter
        lda frame_count
        and #$10
        beq main_loop_damage_colour
        lda #$06
main_loop_damage_colour
        clc
        adc #$01
        sta $db8e,y
        lda damage_letters,x
        sta $0f8e,y
main_loop_damage_next
        dex
        bpl main_loop_damage_loop
        lda invincible                  ; Crash ($4050 set, $4080 clear): runs the crash routine $68fd.
        bne main_loop_check_flag_4089
