        jsr update_mission_end          ; Runs when $4089 is 1 ($6ef9 or $7f2c).
; Sets the difficulty values: $400b = airfields + skill, $4066 = rows to the next airfield, $4067 = skill * 16 + airfields * 8.
main_loop_airfield_gap
        lda airfields_passed
        clc
        adc opt_skill_level
        sta difficulty
        lda airfields_passed
        asl
        asl
        asl
        sta zp_temp0
        ldx opt_skill_level             ; Skill level 0-2 selects the base gap.
        lda random_seed
        and #$07
        adc airfield_gap_base,x
        bcs main_loop_gap_limit
        adc zp_temp0
        bcs main_loop_gap_limit
        cmp #$f0                        ; Limits the gap to $f5.
        bcc main_loop_gap_store
main_loop_gap_limit
; not executed $447a-$447b
        lda #$f5
main_loop_gap_store
        sta airfield_gap
        lda opt_skill_level
        asl
        asl
        asl
        asl
        adc zp_temp0
        sta flak_chance
        jsr animate_chars               ; Animates the charset characters at $23e0.
        jsr next_map_section
